package com.company.project.destination.repository;

/**
 * Set-based statements behind the destination sync, implemented in {@code impl/DestinationSyncRepositoryImpl}.
 * Nothing here can be generated by Spring Data, so this is a plain interface. Every method must run inside the
 * caller's transaction, after {@link #lock()}.
 */
public interface DestinationSyncRepository {

	/** Serializes concurrent runs (several app instances, or startup and cron overlapping). */
	void lock();

	/**
	 * Adds one destination per country / city / district / ward used by a listed hotel that has none yet.
	 * Existing places are left untouched, including everything admins edited.
	 *
	 * @return the number of places created
	 */
	int insertNewPlaces();

	/**
	 * Rewrites a live place's stored spellings when another spelling of the same name has become the most common
	 * among its listed hotels. Its keys, slug and display name stay as they are.
	 */
	void refreshSpellings();

	/**
	 * Recounts the listed hotels inside every live destination. Places that lost all their hotels keep their
	 * row with a count of 0, which hides them from autocomplete.
	 */
	void refreshHotelCounts();

}
